// Package biggingerbuttonv2 is "LordGs big Ginger BUTTon" — a hot-potato
// game for gno.land. Anyone can press the button by sending between 0.1
// and 10 GNOT. Each press resets the countdown. If the countdown ever
// reaches zero, the LAST person who pressed wins the whole pot.
//
// Safety rules baked into the code:
//   - Coins only ever move two ways: into the pot on Press, out to the
//     winner on settlement. There is no owner withdrawal and no admin.
//   - Settlement is permissionless: once the timer expires, ANYONE can
//     trigger the payout with Claim(). Coins can never be locked behind
//     a single person's inaction.
//   - A Press after expiry auto-settles the old round first, so pressing
//     late never loses the previous winner's pot.
//   - Presses are capped at 10 GNOT on-chain, so nobody can accidentally
//     (or maliciously) blow up the stakes beyond the advertised max.
package biggingerbutton

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strings"
	"time"

	"gno.land/p/nt/ufmt/v0"
)

// Game configuration.
var (
	// pressWindow is how long the countdown lasts after each press.
	// It is a var (not a const) only so tests can shorten/expire it;
	// on-chain it stays at 24 hours.
	pressWindow = 24 * time.Hour
	// minPressUgnot is the minimum press fee: 0.1 GNOT.
	minPressUgnot int64 = 100_000
	// maxPressUgnot is the maximum press fee: 10 GNOT.
	maxPressUgnot int64 = 10_000_000
)

// Round state.
var (
	round        int            // current round number (0 = no round played yet)
	active       bool           // a round is running right now
	holder       address        // last presser
	deadline     time.Time      // when the countdown hits zero
	pot          int64          // ugnot currently at stake
	totalPresses int            // presses in the current round
	presses      map[string]int // lifetime presses per address
	lastWinner   address
	lastPot      int64
	lastRound    int
)

// Press the big ginger button. Send between minPressUgnot and
// maxPressUgnot ugnot with the call. The presser becomes the holder and
// the countdown resets to 24h. If the previous round already expired, it
// is settled first (previous holder gets paid) and a new round starts
// with this press.
func Press(cur realm) {
	// Origin calls only: no intermediary realm may press on a user's
	// behalf (it would become the holder and could steal the pot).
	require(cur.Previous().IsUser(), "Press from a user wallet only, no intermediary realms.")
	caller := cur.Previous().Address()
	sent := unsafe.OriginSend()
	amount := int64(sent.AmountOf("ugnot"))
	require(len(sent) == 1 && amount >= minPressUgnot && amount <= maxPressUgnot,
		ufmt.Sprintf("Press needs between %d and %d ugnot (0.1-10 GNOT), nothing else.", minPressUgnot, maxPressUgnot))

	now := time.Now()
	settleIfExpired(cur, now)

	if !active {
		round++
		totalPresses = 0
		pot = 0
	}
	active = true
	holder = caller
	deadline = now.Add(pressWindow)
	pot += amount
	totalPresses++
	if presses == nil {
		presses = map[string]int{}
	}
	presses[caller.String()]++
}

// Claim pays the pot to the last presser once the countdown has reached
// zero. Anyone may call it — the payout always goes to the holder, never
// to the caller. If the timer has not expired yet, Claim panics.
func Claim(cur realm) {
	require(cur.Previous().IsUser(), "Claim from a user wallet only, no intermediary realms.")
	require(active, "No round is running. Press the button to start one!")
	now := time.Now()
	require(!now.Before(deadline),
		ufmt.Sprintf("Button is still hot! %s left on the clock.", formatDuration(deadline.Sub(now))))
	settle(cur)
}

// settleIfExpired pays out and resets the round if the deadline has passed.
func settleIfExpired(cur realm, now time.Time) {
	if active && !now.Before(deadline) {
		settle(cur)
	}
}

// settle sends the whole pot to the holder and closes the round.
// This is the ONLY place coins leave the realm.
func settle(cur realm) {
	winner := holder
	winnings := pot
	lastWinner = winner
	lastPot = winnings
	lastRound = round
	active = false
	holder = ""
	deadline = time.Time{}
	pot = 0
	totalPresses = 0

	if winnings > 0 {
		b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		b.SendCoins(cur.Address(), winner, chain.Coins{{"ugnot", winnings}})
	}
}

// --- read-only helpers (usable via query/eval) ---

// Pot returns the current pot in ugnot.
func Pot() int64 { return pot }

// Round returns the current round number.
func Round() int { return round }

// Holder returns the address of the last presser (empty if no round).
func Holder() address { return holder }

// IsActive reports whether a round is currently running.
func IsActive() bool { return active }

// TimeLeft returns seconds left on the countdown (0 if expired/inactive).
func TimeLeft() int64 {
	if !active {
		return 0
	}
	s := int64(time.Until(deadline).Seconds())
	if s < 0 {
		return 0
	}
	return s
}

// TotalPresses returns the number of presses in the current round.
func TotalPresses() int { return totalPresses }

// LastWinner returns winner and pot of the last settled round.
func LastWinner() (address, int64, int) { return lastWinner, lastPot, lastRound }

// MinPress returns the minimum press in ugnot.
func MinPress() int64 { return minPressUgnot }

// MaxPress returns the maximum press in ugnot.
func MaxPress() int64 { return maxPressUgnot }

// --- rendering ---

// Render implements the gnoweb-facing markdown page.
func Render(path string) string {
	if path != "" {
		return "404 — try the home page."
	}
	var sb strings.Builder
	sb.WriteString("# LordGs big Ginger BUTTon\n\n")
	sb.WriteString("## How to play (super simple)\n\n")
	sb.WriteString("1. **Press the button.** Call `Press()` with between **0.1 and 10 GNOT** attached.\n")
	sb.WriteString("2. **The 24 hour countdown resets** and your address becomes the holder.\n")
	sb.WriteString("3. **If the countdown hits zero and you pressed last, you win the WHOLE pot.**\n")
	sb.WriteString("4. After it hits zero, anyone can call `Claim()` — the pot always goes to the last presser.\n\n")
	sb.WriteString("Every press adds your GNOT to the pot, so the longer the game runs, the bigger the prize.\n\n")

	sb.WriteString("## Game status\n\n")
	now := time.Now()
	if active {
		if now.Before(deadline) {
			sb.WriteString(ufmt.Sprintf("- Round: **%d**\n", round))
			sb.WriteString(ufmt.Sprintf("- Time left: **%s**\n", formatDuration(deadline.Sub(now))))
			sb.WriteString(ufmt.Sprintf("- Current holder (winning right now): `%s`\n", holder.String()))
			sb.WriteString(ufmt.Sprintf("- Pot: **%s GNOT**\n", formatGnot(pot)))
			sb.WriteString(ufmt.Sprintf("- Presses this round: **%d**\n", totalPresses))
			sb.WriteString("\nSomeone can still steal the pot — press the button before the clock runs out!\n")
		} else {
			sb.WriteString(ufmt.Sprintf("- Round **%d** is OVER — the countdown hit zero!\n", round))
			sb.WriteString(ufmt.Sprintf("- Winner: `%s`\n", holder.String()))
			sb.WriteString(ufmt.Sprintf("- Prize waiting: **%s GNOT**\n", formatGnot(pot)))
			sb.WriteString("\nCall `Claim()` to send the pot to the winner and clear the table.\n")
		}
	} else {
		sb.WriteString("The button is cold. Nobody is holding it.\n\n")
		sb.WriteString(ufmt.Sprintf("Be the first to press and start round %d!\n", round+1))
	}

	if lastPot > 0 {
		sb.WriteString("\n## Last round\n\n")
		sb.WriteString(ufmt.Sprintf("- Round %d winner: `%s`\n", lastRound, lastWinner.String()))
		sb.WriteString(ufmt.Sprintf("- Won: **%s GNOT**\n", formatGnot(lastPot)))
	}

	sb.WriteString("\n---\n")
	sb.WriteString("*All rules live in this realm's public source. Coins only ever move from pressers into the pot, and from the pot to the winner. No owner, no fees, no tricks.*\n")
	return sb.String()
}

// formatDuration renders d as "23h 59m 12s".
func formatDuration(d time.Duration) string {
	if d < 0 {
		d = 0
	}
	total := int64(d / time.Second)
	h := total / 3600
	m := (total % 3600) / 60
	s := total % 60
	return ufmt.Sprintf("%dh %dm %ds", h, m, s)
}

// formatGnot renders ugnot as a decimal GNOT string, e.g. 1234567 -> "1.234567".
func formatGnot(ugnot int64) string {
	whole := ugnot / 1_000_000
	frac := ugnot % 1_000_000
	if frac == 0 {
		return ufmt.Sprintf("%d", whole)
	}
	fs := ufmt.Sprintf("%06d", frac)
	for strings.HasSuffix(fs, "0") {
		fs = fs[:len(fs)-1]
	}
	return ufmt.Sprintf("%d.%s", whole, fs)
}

func require(cond bool, msg string) {
	if !cond {
		panic(msg)
	}
}

package bountyboard

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

type TaskStatus int

const (
	StatusOpen TaskStatus = iota
	StatusClaimed
	StatusApproved
	StatusExpiredPaid
	StatusCancelled
	StatusRefundedNoSubmission
)

func (s TaskStatus) String() string {
	switch s {
	case StatusOpen:
		return "Open"
	case StatusClaimed:
		return "Claimed"
	case StatusApproved:
		return "Approved"
	case StatusExpiredPaid:
		return "ExpiredPaid"
	case StatusCancelled:
		return "Cancelled"
	case StatusRefundedNoSubmission:
		return "RefundedNoSubmission"
	default:
		return "Unknown"
	}
}

type Submission struct {
	Claimer address
	Content string
	AtBlock int64
	Seq     int64
}

type Task struct {
	ID             int64
	Owner          address
	Title          string
	Description    string
	Reward         int64
	DeadlineHeight int64
	Status         TaskStatus
	Claimers       *avl.Tree
	Submissions    *avl.Tree
	SubmitCount    int64
	Winner         address
	CreatedAtBlock int64
}

var (
	tasks       = avl.NewTree()
	nextTaskID  int64
	totalLocked int64
)

func CreateTask(cur realm, title, description string, blocksUntilDeadline int64) int64 {
	if !cur.Previous().IsUserCall() {
		panic("bountyboard: only direct user calls (maketx call) can create tasks")
	}
	if blocksUntilDeadline <= 0 {
		panic("bountyboard: blocksUntilDeadline must be positive")
	}
	if title == "" {
		panic("bountyboard: title cannot be empty")
	}

	sent := unsafe.OriginSend()
	reward := sent.AmountOf("ugnot")
	if reward <= 0 {
		panic("bountyboard: task must be created with a positive ugnot reward")
	}

	caller := cur.Previous().Address()
	nowHeight := runtime.ChainHeight()

	nextTaskID++
	id := nextTaskID

	task := &Task{
		ID:             id,
		Owner:          caller,
		Title:          title,
		Description:    description,
		Reward:         reward,
		DeadlineHeight: nowHeight + blocksUntilDeadline,
		Status:         StatusOpen,
		Claimers:       avl.NewTree(),
		Submissions:    avl.NewTree(),
		CreatedAtBlock: nowHeight,
	}

	tasks.Set(itoa(id), task)
	totalLocked += reward

	return id
}

func ClaimTask(cur realm, taskID int64) {
	if !cur.Previous().IsUserCall() {
		panic("bountyboard: only direct user calls can claim tasks")
	}

	task := mustGetTask(taskID)
	caller := cur.Previous().Address()

	if task.Status != StatusOpen && task.Status != StatusClaimed {
		panic("bountyboard: task is not open for claims (status=" + task.Status.String() + ")")
	}
	if runtime.ChainHeight() >= task.DeadlineHeight {
		panic("bountyboard: task deadline has passed")
	}
	if caller == task.Owner {
		panic("bountyboard: task owner cannot claim their own task")
	}
	if task.Claimers.Get(caller.String()) != nil {
		panic("bountyboard: address already claimed this task")
	}

	task.Claimers.Set(caller.String(), true)
	task.Status = StatusClaimed
}

func SubmitWork(cur realm, taskID int64, content string) {
	if !cur.Previous().IsUserCall() {
		panic("bountyboard: only direct user calls can submit work")
	}
	if content == "" {
		panic("bountyboard: submission content cannot be empty")
	}

	task := mustGetTask(taskID)
	caller := cur.Previous().Address()

	if task.Status != StatusClaimed {
		panic("bountyboard: task is not in claimed state (status=" + task.Status.String() + ")")
	}
	if runtime.ChainHeight() >= task.DeadlineHeight {
		panic("bountyboard: task deadline has passed")
	}
	if task.Claimers.Get(caller.String()) == nil {
		panic("bountyboard: caller has not claimed this task")
	}
	if task.Submissions.Get(caller.String()) != nil {
		panic("bountyboard: caller has already submitted work for this task")
	}

	task.SubmitCount++
	task.Submissions.Set(caller.String(), &Submission{
		Claimer: caller,
		Content: content,
		AtBlock: runtime.ChainHeight(),
		Seq:     task.SubmitCount,
	})
}

func ApproveSubmission(cur realm, taskID int64, winner address) {
	if !cur.Previous().IsUserCall() {
		panic("bountyboard: only direct user calls can approve submissions")
	}

	task := mustGetTask(taskID)
	caller := cur.Previous().Address()

	if caller != task.Owner {
		panic("bountyboard: only the task owner can approve a submission")
	}
	if task.Status != StatusClaimed {
		panic("bountyboard: task has no pending submissions to approve (status=" + task.Status.String() + ")")
	}
	if task.Submissions.Get(winner.String()) == nil {
		panic("bountyboard: chosen winner has not submitted work for this task")
	}

	task.Status = StatusApproved
	task.Winner = winner
	reward := task.Reward
	totalLocked -= reward

	payout(cur, winner, reward)
}

func CancelTask(cur realm, taskID int64) {
	if !cur.Previous().IsUserCall() {
		panic("bountyboard: only direct user calls can cancel tasks")
	}

	task := mustGetTask(taskID)
	caller := cur.Previous().Address()

	if caller != task.Owner {
		panic("bountyboard: only the task owner can cancel")
	}
	if task.Status != StatusOpen && task.Status != StatusClaimed {
		panic("bountyboard: task cannot be cancelled in status=" + task.Status.String())
	}
	if task.Submissions.Size() > 0 {
		panic("bountyboard: cannot cancel a task that already has submissions")
	}

	task.Status = StatusCancelled
	reward := task.Reward
	totalLocked -= reward

	payout(cur, task.Owner, reward)
}

func SettleExpired(cur realm, taskID int64) {
	task := mustGetTask(taskID)

	if task.Status != StatusOpen && task.Status != StatusClaimed {
		panic("bountyboard: task is not in a settleable state (status=" + task.Status.String() + ")")
	}
	if runtime.ChainHeight() < task.DeadlineHeight {
		panic("bountyboard: task deadline has not passed yet")
	}

	reward := task.Reward

	if task.Submissions.Size() == 0 {
		task.Status = StatusRefundedNoSubmission
		totalLocked -= reward
		payout(cur, task.Owner, reward)
		return
	}

	winner := firstSubmitter(task)

	task.Status = StatusExpiredPaid
	task.Winner = winner
	totalLocked -= reward
	payout(cur, winner, reward)
}

func mustGetTask(taskID int64) *Task {
	raw := tasks.Get(itoa(taskID))
	if raw == nil {
		panic("bountyboard: task not found")
	}
	task, ok := raw.(*Task)
	if !ok {
		panic("bountyboard: internal error, corrupted task entry")
	}
	return task
}

func firstSubmitter(task *Task) address {
	var winner address
	var minSeq int64 = -1

	task.Submissions.Iterate("", "", func(key string, value interface{}) bool {
		sub, ok := value.(*Submission)
		if !ok {
			return false
		}
		if minSeq == -1 || sub.Seq < minSeq {
			minSeq = sub.Seq
			winner = sub.Claimer
		}
		return false
	})

	if minSeq == -1 {
		panic("bountyboard: internal error, no submissions found despite Size()>0")
	}
	return winner
}

func payout(cur realm, to address, amount int64) {
	realmAddr := cur.Address()
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)

	have := b.GetCoins(realmAddr).AmountOf("ugnot")
	if have < amount {
		panic("bountyboard: internal invariant violation, insufficient realm balance for payout")
	}

	b.SendCoins(realmAddr, to, chain.Coins{chain.NewCoin("ugnot", amount)})
}

func itoa(i int64) string {
	return ufmt.Sprintf("%d", i)
}

func GetTaskStatus(taskID int64) string {
	return mustGetTask(taskID).Status.String()
}

func GetTaskReward(taskID int64) int64 {
	return mustGetTask(taskID).Reward
}

func GetTaskOwner(taskID int64) address {
	return mustGetTask(taskID).Owner
}

func GetTaskDeadlineHeight(taskID int64) int64 {
	return mustGetTask(taskID).DeadlineHeight
}

func GetTaskWinner(taskID int64) address {
	return mustGetTask(taskID).Winner
}

func GetSubmissionCount(taskID int64) int64 {
	return int64(mustGetTask(taskID).Submissions.Size())
}

func TotalLocked() int64 {
	return totalLocked
}
